Hub.GrabDroppedGun = function(self)
	local lp = self.Services.Players.LocalPlayer;
	if not self:IsPlayerInRound(lp) then
		return;
	end
	local char = lp.Character;
	local hum = char and char:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\116\16\142\200\56\211\66\88", "\43\60\101\227\169\86\188"));
	local root = self:GetRoot(char);
	if not (char and root and hum and (hum.Health > 0)) then
		return;
	end
	local bp = lp:FindFirstChildOfClass("Backpack");
	if (char:FindFirstChild("Gun") or (bp and bp:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\87\221\223", "\87\16\168\177\223\58\172\217")))) then
		return;
	end
	local handle = self:GetDroppedGunPart();
	if not handle then
		return;
	end
	if self.State.GrabbingGun then
		return;
	end
	self.State.GrabbingGun = true;
	task.spawn(function()
		pcall(function()
			local myPos = root.Position;
			local gunPos = handle.Position;
			local dist = (gunPos - myPos).Magnitude;
			pcall(function()
				if handle:IsA("BasePart") then
					handle.CFrame = root.CFrame;
				end
			end);
			if ((dist <= 12) and firetouchinterest) then
				for _, part in ipairs({root,char:FindFirstChild("RightHand"),char:FindFirstChild("Right Arm"),char:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\24\200\95\201\29\59\194\77", "\91\84\173\57\189"))}) do
					if part then
						firetouchinterest(part, handle, 0);
						firetouchinterest(part, handle, 1);
					end
				end
			else
				local oldCF = root.CFrame;
				local oldVel = root.AssemblyLinearVelocity;
				local targetCF = handle.CFrame + Vector3.new(0, 1.2, 0);
				local startTime = tick();
				while (tick() - startTime) < 0.45 do
					if (char:FindFirstChild("Gun") or (bp and bp:FindFirstChild("Gun"))) then
						break;
					end
					if (not handle or not handle.Parent) then
						break;
					end
					root.AssemblyLinearVelocity = Vector3.zero;
					root.CFrame = targetCF;
					if firetouchinterest then
						firetouchinterest(root, handle, 0);
						firetouchinterest(root, handle, 1);
					end
					task.wait(0.05);
				end
				root.CFrame = oldCF;
				root.AssemblyLinearVelocity = oldVel;
			end
		end);
		task.wait(0.3);
		self.State.GrabbingGun = false;
	end);
end;
