Hub.SetupPreview = function(self, container)
	local vp = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\156\1\77\248\155\165\26\92\201\153\171\5\77", "\235\202\104\40\143"));
	vp.Name = "CharacterPreview";
