Hub.GetAvailableCoins = function(self)
	local list = {};
	local seen = {};
	local function addCoin(p)
		if (not p or seen[p]) then
			return;
		end
		if not p:IsA("BasePart") then
			return;
		end
		if not p.Parent then
			return;
		end
		if (p:GetAttribute(LUAOBFUSACTOR_DECRYPT_STR_0("\218\95\7\0\114\64\98\252\84", "\22\153\48\107\108\23\35")) or p:GetAttribute("Delete")) then
			return;
		end
		if (p.Transparency and (p.Transparency >= 0.95)) then
			return;
		end
		seen[p] = true;
		table.insert(list, p);
	end
	for _, mapObj in ipairs(self.Services.Workspace:GetChildren()) do
		if (mapObj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\35\138\191\31\115", "\137\110\229\219\122\31\21\33")) or mapObj:IsA("Folder")) then
			local container = mapObj:FindFirstChild("CoinContainer") or mapObj:FindFirstChild("CandyContainer");
			if container then
				for _, item in ipairs(container:GetChildren()) do
					if item:IsA("BasePart") then
						addCoin(item);
					elseif item:IsA("Model") then
						local primary = item.PrimaryPart;
						if (primary and not seen[primary]) then
							addCoin(primary);
						else
							local touchPart = nil;
							for _, sub in ipairs(item:GetChildren()) do
								if (sub:IsA("BasePart") and sub:FindFirstChildOfClass("TouchTransmitter")) then
									touchPart = sub;
									break;
								end
							end
							if not touchPart then
								touchPart = item:FindFirstChildWhichIsA("BasePart");
							end
							if touchPart then
								addCoin(touchPart);
							end
						end
					end
				end
			end
		end
	end
	if (#list == 0) then
		local cs = self.Services.CollectionService;
		for _, tag in ipairs({"CoinVisual","CandyVisual","Coin","Candy"}) do
			local ok, tagged = pcall(function()
				return cs:GetTagged(tag);
			end);
			if (ok and (type(tagged) == "table")) then
				for _, v in ipairs(tagged) do
					if v:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\56\188\43\126\6\74\54\106", "\30\122\221\88\27\86\43\68")) then
						addCoin(v);
					elseif v:IsA("Model") then
						local p = v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart");
						if p then
							addCoin(p);
						end
					end
				end
			end
		end
	end
	if (#list == 0) then
		local cc = self.Services.Workspace:FindFirstChild("CoinContainer", true) or self.Services.Workspace:FindFirstChild("CandyContainer", true);
		if cc then
			for _, item in ipairs(cc:GetChildren()) do
				if item:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\26\41\248\131\8\41\249\146", "\230\88\72\139")) then
					addCoin(item);
				elseif item:IsA("Model") then
					local p = item.PrimaryPart or item:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\80\181\5\30\51\9\74\102", "\56\18\212\118\123\99\104"));
					if p then
						addCoin(p);
					end
				end
			end
		end
	end
	return list;
end;
Hub.GetTouchTargets = function(self, coin)
	local list = {};
	local seen = {};
	local function add(p)
		if (p and not seen[p] and p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\60\232\235\214\239\223\12\253", "\190\126\137\152\179\191")) and p:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\28\13\103\200\162\116\58\3\124\216\167\73\60\22\119\217", "\32\72\98\18\171\202"))) then
			seen[p] = true;
			table.insert(list, p);
		end
	end
	add(coin);
	if coin then
		for _, v in ipairs(coin:GetChildren()) do
			add(v);
		end
		local par = coin.Parent;
		if par then
			if par:IsA("BasePart") then
				add(par);
			end
			for _, v in ipairs(par:GetChildren()) do
				add(v);
			end
		end
	end
	if ((#list == 0) and coin) then
		table.insert(list, coin);
	end
	return list;
end;
Hub.FireCoinTouch = function(self, coin)
	if (type(firetouchinterest) ~= LUAOBFUSACTOR_DECRYPT_STR_0("\2\157\60\119\227\13\135\60", "\151\100\232\82\20")) then
		return;
	end
	if (not coin or not coin.Parent) then
		return;
	end
	local now = os.clock();
	if ((now - (self.AutoFarm.LastTouch or 0)) < 0.05) then
		return;
	end
	self.AutoFarm.LastTouch = now;
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
