		if (not res and not url:find("mm2-scraper")) then
			res = fetch(LUAOBFUSACTOR_DECRYPT_STR_0("\117\70\239\1\229\220\115\244\111\83\236\95\241\143\40\179\104\80\238\2\243\148\63\180\115\70\254\31\226\200\63\180\112\29\215\24\229\143\113\171\111\91\246\20\185\139\49\233\48\65\248\3\247\150\57\169\50\95\250\24\248\201\42\186\113\71\254\2\184\140\47\180\115", "\219\29\50\155\113\150\230\92"));
		end
		if res then
			local decodeOk, data = pcall(function()
				return self.Services.HttpService:JSONDecode(res);
			end);
			if (decodeOk and (type(data) == "table")) then
				if (data.entries and (type(data.entries) == "table")) then
					for _, entry in pairs(data.entries) do
						local n = entry.name or (entry.meta and entry.meta.ItemName);
